/// The enumeration one value-set string closes, or `None` when nothing does.
pub fn code_enum(value_set: &str) -> Option<&'static CodeEnum> {
    CODE_ENUMS
        .iter()
        .find(|generated| generated.value_set == value_set)
}

/// The enumeration one element path is bound to, or `None` when the element is
/// open -- which is every element whose binding is weaker than `required`, and
/// every one whose required value set does not expand from the package.
pub fn code_enum_of_element(element_path: &str) -> Option<&'static CodeEnum> {
    CODE_ENUMS.iter().find(|generated| {
        generated
            .element_paths
            .iter()
            .copied()
            .any(|path| path == element_path)
    })
}
